mapper.select:
SELECT c.note_id,c.id AS chunk_id,n.title,c.heading_path,c.start_line,c.end_line,c.content,1-(c.embedding <=> CAST(#{queryVector} AS vector)) AS score
FROM note_chunk c JOIN note n ON n.id=c.note_id AND n.owner_id=c.owner_id
WHERE c.owner_id=#{ownerId} AND n.owner_id=#{ownerId} AND n.status='READY' AND c.embedding_model=#{embeddingModel}
AND n.id IN #{id}
AND 1-(c.embedding <=> CAST(#{queryVector} AS vector)) >= #{minScore}
ORDER BY c.embedding <=> CAST(#{queryVector} AS vector),c.id LIMIT #{limit}
